parameters.query:
SELECT source, content, score
FROM kb_search(
  (SELECT array_agg(x::float8) FROM json_array_elements_text($1::json) AS x),
  $2,
  5
);

parameters.jsCode:
// The refusal happens HERE, before the model is called.
//
// Why not let the model refuse? Because a model handed five irrelevant chunks and
// asked a question will usually find something in them to build an answer out of -
// that is the thing it is good at. The similarity score already knows there is
// nothing relevant before the model gets a chance to be helpful about it.
//
// Refusing at retrieval means the refusal does not depend on the model being in the
// mood to refuse.
//
// 0.28 is not a guess. Measured on this document pack:
//     a question the documents answer  ->  0.35 to 0.59
//     a question they do not           ->  0.12 to 0.26
// 0.28 sits in the empty band between them. Watch your own numbers and move it if
// your documents score differently.
const THRESHOLD = 0.28;

// Word-for-word what the model is told to say when the context comes up short, so a
// refusal reads identically whether it was caught here or by the model downstream.
const NO_ANSWER = "I don't have that in your documents.";

const rows = $input.all().map(i => i.json).filter(r => r && r.content);
const question = $('Ask').first().json.body?.question ?? '';
const best = rows.length ? Math.max(...rows.map(r => Number(r.score) || 0)) : 0;

if (!rows.length || best < THRESHOLD) {
  return [{ json: {
    answered: false,
    answer: NO_ANSWER,
    sources: [],
    top_score: best
  }}];
}

const context = rows
  .map(r => `[${r.source}]\n${r.content}`)
  .join('\n\n---\n\n');

return [{ json: {
  question,
  context,
  sources: [...new Set(rows.map(r => r.source))],
  top_score: best
}}];

parameters.jsonBody:
={{ JSON.stringify({
  model: "anthropic/claude-haiku-4.5",
  temperature: 0,
  messages: [
    { role: "system", content: "You answer questions about the user's own documents. Use ONLY the numbered context below. Do not use outside knowledge. If the context does not contain the answer, set answer to exactly: I don't have that in your documents. When you do answer, be specific and quote the figure or term. Two sentences or fewer. Reply with a JSON object only: {\"answer\": \"...\", \"used_sources\": [\"filename\"]}" },
    { role: "user", content: "Context:\n\n" + $json.context + "\n\nQuestion: " + $json.question }
  ]
}) }}

parameters.jsCode:
// Strip the code fence before parsing. Assume it is there.
//
// The system prompt says "JSON object only". Measured in Class 2: the model returned
// a ```json fence on 4 of 4 calls anyway. Status 200, content correct, JSON.parse
// throws - and the error points at THIS node instead of at the model.
//
// The lesson is not "ask for JSON". It is: never trust a model to respect your
// output format.
const raw = $json.choices?.[0]?.message?.content ?? '';
const clean = raw.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();

const meta = $('Decide').first().json;

let out;
try {
  out = JSON.parse(clean);
} catch (e) {
  // A failed parse must not take the request down. Hand back what it said.
  out = { answer: clean || 'The model returned nothing readable.', used_sources: [] };
}

const answer = String(out.answer ?? '').trim();

// The model can still refuse even when retrieval let it through - the chunks cleared
// the score bar but did not actually contain the answer. That is a refusal too, and
// it has to be reported as one, or the dashboard renders "I don't have that in your
// documents" styled as a confident answer with sources attached to it.
const refused = /don't have that in your documents/i.test(answer);

return [{ json: {
  answered: !refused,
  answer,
  sources: refused ? [] : ((out.used_sources?.length ? out.used_sources : meta.sources) || []),
  top_score: meta.top_score
}}];
